/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'fs'

// Parse command-line arguments
const args = process.argv.slice(2)
if (args.length === 0 || (args[0] !== 'waves' && args[0] !== 'explain' && args[0] !== 'pack')) {
  process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n')
  process.exit(2)
}

const command = args[0]
let workers = 1

if (command === 'pack') {
  if (args.length < 2) {
    process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n')
    process.exit(2)
  }
  const workerStr = args[1]
  if (!/^[1-9]\d*$/.test(workerStr)) {
    process.stderr.write('error: workers must be a positive integer\n')
    process.exit(2)
  }
  workers = parseInt(workerStr, 10)
}

// Read stdin
const input = readFileSync(0, 'utf-8')

// Parse the build graph
const lines = input.split('\n')
const tasks = new Map() // name -> cost
const deps = new Map() // name -> Set of dependency names

let lineNum = 0
const errors = []

for (const rawLine of lines) {
  lineNum++
  let line = rawLine.trim()

  // Skip empty lines and comments
  if (!line || line.startsWith('#')) {
    continue
  }

  const words = line.split(/\s+/)
  if (words.length === 0) {
    continue
  }

  const directive = words[0]

  if (directive === 'task') {
    if (words.length !== 3) {
      process.stderr.write(`error: line ${lineNum}: expected task <name> <cost>\n`)
      process.exit(2)
    }

    const name = words[1]
    const costStr = words[2]

    // Validate task name
    if (!/^[A-Za-z0-9_.\-]+$/.test(name)) {
      process.stderr.write(`error: line ${lineNum}: invalid task name ${name}\n`)
      process.exit(2)
    }

    // Check for duplicate task declaration
    if (tasks.has(name)) {
      process.stderr.write(`error: line ${lineNum}: task ${name} is declared twice\n`)
      process.exit(2)
    }

    // Validate cost (non-negative integer, no leading zero unless it's just "0")
    if (!/^\d+$/.test(costStr) || (costStr.length > 1 && costStr[0] === '0')) {
      process.stderr.write(`error: line ${lineNum}: cost must be a non-negative integer\n`)
      process.exit(2)
    }

    const cost = parseInt(costStr, 10)
    tasks.set(name, cost)
  } else if (directive === 'dep') {
    if (words.length < 2) {
      process.stderr.write(`error: line ${lineNum}: expected dep <name> <dependency>...\n`)
      process.exit(2)
    }

    const name = words[0]
    const dependencies = words.slice(1)

    if (!deps.has(name)) {
      deps.set(name, new Set())
    }

    for (const dep of dependencies) {
      deps.get(name).add(dep)
    }
  } else {
    process.stderr.write(`error: line ${lineNum}: unknown directive ${directive}\n`)
    process.exit(2)
  }
}

// Check that all referenced tasks exist
for (const [name, depSet] of deps.entries()) {
  for (const dep of depSet) {
    if (!tasks.has(dep)) {
      process.stderr.write(`error: unknown task ${dep}\n`)
      process.exit(2)
    }
  }
}

// Check for cycles using DFS
function detectCycle() {
  const visited = new Set()
  const recStack = new Set()
  const path = []

  function dfs(node) {
    visited.add(node)
    recStack.add(node)
    path.push(node)

    const nodeDeps = deps.get(node) || new Set()
    const sortedDeps = Array.from(nodeDeps).sort()

    for (const dep of sortedDeps) {
      if (!visited.has(dep)) {
        const cycle = dfs(dep)
        if (cycle) return cycle
      } else if (recStack.has(dep)) {
        // Found a cycle
        const cycleStart = path.indexOf(dep)
        const cycle = path.slice(cycleStart).concat([dep])
        return cycle
      }
    }

    path.pop()
    recStack.delete(node)
    return null
  }

  // Check each task in ascending name order
  const sortedTasks = Array.from(tasks.keys()).sort()
  for (const task of sortedTasks) {
    if (!visited.has(task)) {
      const cycle = dfs(task)
      if (cycle) return cycle
    }
  }

  return null
}

const cycle = detectCycle()
if (cycle) {
  const cycleStr = cycle.join(' -> ')
  process.stderr.write(`error: cycle: ${cycleStr}\n`)
  process.exit(3)
}

// Calculate start and finish times for each task
function calculateTimes() {
  const start = new Map()
  const finish = new Map()

  function getFinish(name) {
    if (finish.has(name)) {
      return finish.get(name)
    }

    let taskStart = 0
    const taskDeps = deps.get(name) || new Set()
    for (const dep of taskDeps) {
      taskStart = Math.max(taskStart, getFinish(dep))
    }
    start.set(name, taskStart)
    const taskFinish = taskStart + tasks.get(name)
    finish.set(name, taskFinish)
    return taskFinish
  }

  for (const name of tasks.keys()) {
    getFinish(name)
  }

  return { start, finish }
}

const { start, finish } = calculateTimes()

// Calculate wave (depth) for each task
function calculateWaves() {
  const depth = new Map()

  function getDepth(name) {
    if (depth.has(name)) {
      return depth.get(name)
    }

    let maxDepth = 0
    const taskDeps = deps.get(name) || new Set()
    for (const dep of taskDeps) {
      maxDepth = Math.max(maxDepth, getDepth(dep) + 1)
    }
    depth.set(name, maxDepth)
    return maxDepth
  }

  for (const name of tasks.keys()) {
    getDepth(name)
  }

  // Group tasks by depth
  const waves = new Map()
  for (const [name, d] of depth.entries()) {
    if (!waves.has(d)) {
      waves.set(d, [])
    }
    waves.get(d).push(name)
  }

  // Sort tasks within each wave
  for (const wave of waves.values()) {
    wave.sort()
  }

  return { depth, waves }
}

const { depth, waves } = calculateWaves()

// Calculate the makespan (unlimited workers)
let makespan = 0
for (const f of finish.values()) {
  makespan = Math.max(makespan, f)
}

// Execute command
if (command === 'waves') {
  const sortedWaves = Array.from(waves.keys()).sort((a, b) => a - b)
  for (const w of sortedWaves) {
    const taskNames = waves.get(w).join(' ')
    console.log(`wave ${w}: ${taskNames}`)
  }
  console.log(`total ${makespan}`)
} else if (command === 'explain') {
  const sortedTasks = Array.from(tasks.keys()).sort()
  for (const name of sortedTasks) {
    const s = start.get(name)
    const f = finish.get(name)
    const d = depth.get(name)
    console.log(`${name} start=${s} finish=${f} depth=${d}`)
  }
  console.log(`total ${makespan}`)
} else if (command === 'pack') {
  // Simulate scheduling on workers
  const workerTasks = Array.from({ length: workers }, () => [])
  const workerFree = Array.from({ length: workers }, () => 0) // when each worker becomes free
  const finished = new Set() // finished tasks

  // Calculate priority for each task: longest chain starting from this task
  function calculatePriority(name, memo = new Map()) {
    if (memo.has(name)) {
      return memo.get(name)
    }

    let priority = tasks.get(name) // cost of this task

    // Find all tasks that depend on this one
    for (const [depName, depSet] of deps.entries()) {
      if (depSet.has(name)) {
        priority = Math.max(priority, tasks.get(name) + calculatePriority(depName, memo))
      }
    }

    memo.set(name, priority)
    return priority
  }

  const priorityMemo = new Map()

  while (finished.size < tasks.size) {
    // Find all ready tasks (all dependencies finished)
    const ready = []
    for (const [taskName, cost] of tasks.entries()) {
      if (finished.has(taskName)) continue

      const taskDeps = deps.get(taskName) || new Set()
      let allDepsFinished = true
      for (const dep of taskDeps) {
        if (!finished.has(dep)) {
          allDepsFinished = false
          break
        }
      }

      if (allDepsFinished) {
        ready.push(taskName)
      }
    }

    // Sort ready tasks by priority (descending) and name (ascending)
    ready.sort((a, b) => {
      const pA = calculatePriority(a, priorityMemo)
      const pB = calculatePriority(b, priorityMemo)
      if (pA !== pB) return pB - pA // higher priority first
      return a.localeCompare(b) // then by name
    })

    // Assign ready tasks to free workers
    let assigned = false
    for (let i = 0; i < workers && ready.length > 0; i++) {
      if (workerFree[i] <= Math.min(...workerFree)) {
        const task = ready.shift()
        const taskStart = workerFree[i]
        const taskFinish = taskStart + tasks.get(task)
        workerTasks[i].push({ name: task, start: taskStart, finish: taskFinish })
        workerFree[i] = taskFinish
        finished.add(task)
        assigned = true
      }
    }

    if (!assigned) {
      // Find next time when a worker becomes free
      let nextTime = Math.min(...workerFree)
      for (let i = 0; i < workers; i++) {
        if (workerFree[i] > nextTime && workerFree[i] < Math.max(...workerFree)) {
          nextTime = workerFree[i]
        }
      }
      nextTime = Math.min(...workerFree.filter(t => t > Math.min(...workerFree)))
      if (Number.isFinite(nextTime)) {
        for (let i = 0; i < workers; i++) {
          if (workerFree[i] === nextTime) break
        }
      } else {
        break
      }
    }
  }

  // Output worker schedules
  let maxFinish = 0
  for (let i = 0; i < workers; i++) {
    const taskList = workerTasks[i].map(t => `${t.name}@${t.start}-${t.finish}`).join(' ')
    if (taskList) {
      console.log(`worker ${i}: ${taskList}`)
      maxFinish = Math.max(maxFinish, workerTasks[i][workerTasks[i].length - 1].finish)
    } else {
      console.log(`worker ${i}:`)
    }
  }
  console.log(`makespan ${maxFinish}`)
}
