 * Reading a build graph out of the text on standard input.
 *
 * `parse` returns `{ tasks, deps, order }` where `tasks` maps a name to its
 * cost, `deps` maps a name to the array of names it depends on (each edge
 * once, in first-seen order) and `order` is the task names in declaration
 * order. A failure is reported by throwing a `GraphError`.
 */

export class GraphError extends Error {
  constructor(message, code) {
    super(message)
    this.exitCode = code
  }
}

const NAME = /^[A-Za-z0-9_.-]+$/
const COST = /^[0-9]+$/

/** Names sort by code unit, which is what "ascending name order" means here. */
export function byName(a, b) {
  if (a < b) return -1
  if (a > b) return 1
  return 0
}

/** The lines of the input, without the empty tail a trailing newline leaves. */
export function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

export function parse(input) {
  const tasks = new Map()
  const deps = new Map()
  const order = []
  // Every name a dep line uses, in input order, with nothing repeated.
  const used = []

  const lines = splitLines(input)
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i].trim()
