{"file_path":"src/schedule.js","content":"/**
 * Timing a build graph: waves and unlimited-worker times, and the greedy
 * simulation behind `pack`.
 */

import { byName } from './parse.js'

/** Start, finish and depth of every task, with unlimited workers. */
export function times({ tasks, deps }) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  function visit(name) {
    if (finish.has(name)) return
    let s = 0
    let d = 0
    for (const dep of deps.get(name)) {
      visit(dep)
      s = Math.max(s, finish.get(dep))
      d = Math.max(d, depth.get(dep) + 1)
    }
    start.set(name, s)
    finish.set(name, s + tasks.get(name))
    depth.set(name, d)
  }

  for (const name of tasks.keys()) visit(name)

  let total = 0
  for (const f of finish.values()) total = Math.max(total, f)

  return { start, finish, depth, total }
}

/** Tasks grouped by depth, each wave in ascending name order. */
export function waves(depth) {
  const groups = []
  for (const [name, d] of depth) {
    while (groups.length <= d) groups.push([])
    groups[d].push(name)
  }
  for (const group of groups) group.sort(byName)
  return groups
}

/**
 * The cost of the longest chain that begins at each task, counting its own
 * cost and then the costs down to any task that nothing depends on.
 */
export function priorities({ tasks, deps }) {
  const dependents = new Map([...tasks.keys()].map((n) => [n, []]))
  for (const [name, edges] of deps) {
    for (const dep of edges) dependents.get(dep).push(name)
  }

  const priority = new Map()
  function visit(name) {
    if (priority.has(name)) return priority.get(name)
    let below = 0
    for (const next of dependents.get(name)) below = Math.max(below, visit(next))
    const value = tasks.get(name) + below
    priority.set(name, value)
    return value
  }
  for (const name of tasks.keys()) visit(name)
  return priority
}

/**
 * The greedy simulation: while a worker is free at the current instant and
 * some task is ready, the ready task of greatest priority (ties by ascending
 * name) starts on the free worker of smallest index.
 */
export function pack(graph, workerCount) {
  const { tasks, deps } = graph
  const priority = priorities(graph)
  const names = [...tasks.keys()].sort(byName)

  const runs = Array.from({ length: workerCount }, () => [])
  const free = new Array(workerCount).fill(0)
  const finished = new Map()

  let now = 0
  let makespan = 0

  while (finished.size < tasks.size) {
    const worker = free.indexOf(Math.min(...free)) // smallest index among the earliest
    let best = null
    if (free.some((t) => t <= now)) {
      for (const name of names) {
        if (finished.has(name)) continue
        if (!deps.get(name).every((d) => finished.has(d) && finished.get(d) <= now)) continue
        if (best === null || priority.get(name) > priority.get(best)) best = name
      }
    }

    if (best === null) {
      const later = free.filter((t) => t > now)
      if (later.length === 0) break
      now = Math.min(...later)
      continue
    }

    const slot = free.findIndex((t) => t <= now)
    const finish = now + tasks.get(best)
    runs[slot].push(`${best}@${now}-${finish}`)
    free[slot] = finish
    finished.set(best, finish)
    if (finish > makespan) makespan = finish
    void worker
  }

  return { runs, makespan }
}
"}

