 * The greedy simulation: while a worker is free at the current instant and
 * some task is ready, the ready task of greatest priority (ties by ascending
 * name) starts on the free worker of smallest index.
 */
export function pack(graph, workerCount) {
  const { tasks, deps } = graph
  const priority = priorities(graph)
  const names = [...tasks.keys()].sort(byName)

