  if ((mode === 'waves' || mode === 'explain') && argv.length === 1) {
    return { mode, workers: 0 }
  }
  if (mode === 'pack' && argv.length === 2) {
    const count = argv[1]
    if (!/^[1-9][0-9]*$/.test(count)) fail('error: workers must be a positive integer', 2)
    return { mode, workers: Number(count) }
  }
  return fail(USAGE, 2)
