        out.push(`${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`)
      }
    }
    out.push(`total ${total}`)
  }
  process.stdout.write(out.map((line) => `${line}\n`).join(''))
}

main()
