// Calculate the makespan (unlimited workers)
let makespan = 0
for (const f of finish.values()) {
  makespan = Math.max(makespan, f)
}

// Execute command
if (command === 'waves') {
  const sortedWaves = Array.from(waves.keys()).sort((a, b) => a - b)
  for (const w of sortedWaves) {
    const taskNames = waves.get(w).join(' ')
    console.log(`wave ${w}: ${taskNames}`)
  }
  console.log(`total ${makespan}`)
} else if (command === 'explain') {
  const sortedTasks = Array.from(tasks.keys()).sort()
  for (const name of sortedTasks) {
    const s = start.get(name)
    const f = finish.get(name)
    const d = depth.get(name)
    console.log(`${name} start=${s} finish=${f} depth=${d}`)
  }
  console.log(`total ${makespan}`)
} else if (command === 'pack') {
  // Calculate priority for each task: longest chain starting from this task
  const priority = new Map()

  function calculatePriority(name, memo = new Map()) {
    if (memo.has(name)) {
      return memo.get(name)
    }

    let maxChain = tasks.get(name)

    // Find all tasks that depend on this one
    for (const [depName, depSet] of deps.entries()) {
      if (depSet.has(name)) {
        maxChain = Math.max(maxChain, tasks.get(name) + calculatePriority(depName, memo))
      }
    }

    memo.set(name, maxChain)
    return maxChain
  }

  const priorityMemo = new Map()
  for (const name of tasks.keys()) {
    priority.set(name, calculatePriority(name, priorityMemo))
  }

  // Simulate scheduling on workers
  const workerTasks = Array.from({ length: workers }, () => [])
  const workerFree = Array.from({ length: workers }, () => 0)
  const taskFinishTime = new Map()

  let currentTime = 0

  while (taskFinishTime.size < tasks.size) {
    // Find all ready tasks at current time
    const ready = []
    for (const [taskName, cost] of tasks.entries()) {
      if (taskFinishTime.has(taskName)) continue

      const taskDeps = deps.get(taskName) || new Set()
      let allDepsFinished = true
      for (const dep of taskDeps) {
        const depFinish = taskFinishTime.get(dep)
        if (depFinish === undefined || depFinish > currentTime) {
          allDepsFinished = false
          break
        }
      }

      if (allDepsFinished) {
        ready.push(taskName)
      }
    }

    // Sort ready tasks by priority (descending) then name (ascending)
    ready.sort((a, b) => {
      const pA = priority.get(a)
      const pB = priority.get(b)
      if (pA !== pB) return pB - pA
      return a.localeCompare(b)
    })

    // Assign ready tasks to free workers at current time
    let assigned = false
    for (let i = 0; i < workers && ready.length > 0; i++) {
      if (workerFree[i] <= currentTime) {
        const task = ready.shift()
        const taskStart = currentTime
        const taskFinish = taskStart + tasks.get(task)
        workerTasks[i].push({ name: task, start: taskStart, finish: taskFinish })
        workerFree[i] = taskFinish
        taskFinishTime.set(task, taskFinish)
        assigned = true
      }
    }

    if (!assigned) {
      // Advance time to the next instant when a worker becomes free
      let nextTime = Infinity
      for (let i = 0; i < workers; i++) {
        if (workerFree[i] > currentTime) {
          nextTime = Math.min(nextTime, workerFree[i])
        }
      }

      if (nextTime === Infinity) break
      currentTime = nextTime
    }
  }

  // Output worker schedules
  let maxFinish = 0
  for (let i = 0; i < workers; i++) {
    const taskList = workerTasks[i].map(t => `${t.name}@${t.start}-${t.finish}`).join(' ')
    if (taskList) {
      console.log(`worker ${i}: ${taskList}`)
      maxFinish = Math.max(maxFinish, workerTasks[i][workerTasks[i].length - 1].finish)
    } else {
      console.log(`worker ${i}:`)
    }
  }
  console.log(`makespan ${maxFinish}`)
}

