import { readFileSync } from 'node:fs'
import { GraphError, byName, findCycle, parse } from './parse.js'
import { pack, times, waves } from './schedule.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'

function fail(message, code) {
  process.stderr.write(`${message}\n`)
  process.exit(code)
}

function readMode(argv) {
  const [mode] = argv
  if ((mode === 'waves' || mode === 'explain') && argv.length === 1) {
    return { mode, workers: 0 }
  }
  if (mode === 'pack' && argv.length === 2) {
    const count = argv[1]
    if (!/^[1-9][0-9]*$/.test(count)) fail('error: workers must be a positive integer', 2)
    return { mode, workers: Number(count) }
  }
  return fail(USAGE, 2)
}

function main() {
  const { mode, workers } = readMode(process.argv.slice(2))

  let graph
  try {
    graph = parse(readFileSync(0, 'utf8'))
  } catch (error) {
    if (error instanceof GraphError) fail(error.message, error.exitCode)
    throw error
  }

  const cycle = findCycle(graph)
  if (cycle) fail(`error: cycle: ${cycle.join(' -> ')}`, 3)

  const out = []
  if (mode === 'pack') {
    const { runs, makespan } = pack(graph, workers)
    runs.forEach((run, i) => out.push(`worker ${i}:${run.map((r) => ` ${r}`).join('')}`))
    out.push(`makespan ${makespan}`)
  } else {
    const { start, finish, depth, total } = times(graph)
    if (mode === 'waves') {
      waves(depth).forEach((group, i) => out.push(`wave ${i}: ${group.join(' ')}`))
    } else {
      for (const name of [...graph.tasks.keys()].sort(byName)) {
        out.push(`${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`)
      }
    }
    out.push(`total ${total}`)
  }
  process.stdout.write(out.map((line) => `${line}\n`).join(''))
}

main()
